import {
  ActivityIndicator,
  RefreshControl,
  ScrollView,
  View,
} from 'react-native';
import {styles} from './styles';

import {listActionNext, mockData, mockUserInfo} from './helper';
import BottomItem from './component/bottom-item';
import DetailItem from './component/detail-item';
import {useEffect, useState} from 'react';
import {useRoute} from '@react-navigation/native';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {useAccountInfoServices} from '../../../../../hooks/apiHooks/useAccountInfoServices';
import {IUserInfo} from '../../../../../model/interface/service.interface';
import TextCM from '../../../../components/Text';
import {Color} from '../../../../../constants';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {
  IconCalendarLabel,
  IconLabelKey,
  IconLabelReceiptStatus,
  IconPersonlabel,
} from '../../../../../assets/images';
import {DateUtils} from '../../../../../utils';
import {useQDTHAService} from '../../../../../hooks/apiHooks/useAPI';
import {DetailDYCData} from '../../../../../model/interface/qdtha.interface';
import {
  listRequestStatus,
  listRequestStatusQDTHA,
} from '../modal-filter/helper';
import {useConfigStore} from '../../../zustand/config';

const DetailDYCScreen = () => {
  const QDTHAServices = useQDTHAService();
  const AccountService = useAccountInfoServices();
  const {LIST_APPLICATION_STATUS} = useConfigStore();

  const {t} = useTranslation();
  const router = useRoute<any>();
  const {id} = router.params;

  const [detailDYC, setDetailDYC] = useState<DetailDYCData>(
    {} as DetailDYCData,
  );
  const [createByDetail, setCreateByDetail] = useState<IUserInfo>();
  const [isLoading, setIsLoading] = useState(false);
  const [refreshing, setRefresing] = useState(false);

  const getDataDetail = async (isLoading: boolean) => {
    if (isLoading) {
      setIsLoading(true);
    } else {
      setRefresing(true);
    }
    try {
      const res = (await QDTHAServices.getDetailMyDYC(id)) as DetailDYCData;
      if (res) {
        setDetailDYC(res);
        const filter = {
          logins: [res.createdBy],
        };
        const resCreateBy = await AccountService.getListAccount(filter);
        setCreateByDetail(resCreateBy?.data[0]);
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsLoading(false);
      setRefresing(false);
    }
  };
  useEffect(() => {
    getDataDetail(true);
  }, [id]);

  const StatusTag = ({
    status,
    type,
  }: {
    status: string;
    type: 'DEFAULT' | 'REQUEST' | 'MIX';
  }) => {
    let properties;
    if (type === 'DEFAULT') {
      properties = listRequestStatusQDTHA.find(
        (item: any) => item.value === status,
      );
    } else if (type === 'REQUEST') {
      properties = LIST_APPLICATION_STATUS.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    } else {
      properties = listRequestStatus.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    }
    if (properties) {
      return (
        <View style={{flex: 1, flexDirection: 'row'}}>
          <View
            style={[
              styles.statusTag,
              {backgroundColor: properties?.bgColor || '#EF5DA81A'},
            ]}>
            <TextCM
              style={[
                styles.statusText,
                {color: properties?.color || '#d94936'},
              ]}>
              {type == 'REQUEST'
                ? properties?.label
                : t(`BLDT.${properties?.value}`)}
            </TextCM>
          </View>
          <View style={{flex: 1}} />
        </View>
      );
    }
    return (
      <View style={{flexDirection: 'row', flex: 1}}>
        <View style={[styles.statusTag, {backgroundColor: '#EF5DA81A'}]}>
          <TextCM style={[styles.statusText, {color: Color.QDTHACMColor}]}>
            {t(`BLDT.${status}`)}
          </TextCM>
        </View>
        <View style={{flex: 1}} />
      </View>
    );
  };

  const onRefresh = () => {
    setRefresing(true);
    getDataDetail(false);
  };

  return (
    <>
      <HeaderCM
        title={'Chi tiết đơn yêu cầu'}
        useLinearGradient={false}
        style={{backgroundColor: Color.QDTHACMColor}}
        contentStyle={{backgroundColor: Color.QDTHACMColor}}
      />
      {isLoading ? (
        <View style={{flex: 1, justifyContent: 'center', alignItems: 'center'}}>
          <ActivityIndicator color={Color.QDTHACMColor} size={'large'} />
        </View>
      ) : (
        <ScrollView
          refreshControl={
            <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
          }
          style={styles.content}>
          <View style={styles.titleSection}>
            <TextCM style={styles.titleText}>
              {detailDYC?.attrs?.name || '---'}
            </TextCM>
            <TextCM style={styles.idText}>
              {detailDYC?.attrs?.requestCode || '---'}
            </TextCM>
          </View>

          <View style={styles.detailsSection}>
            <DetailItem
              icon={<IconCalendarLabel width={16} height={16} />}
              label={t('CM.createDateCard')}
              value={DateUtils.convertDateToDDMMYYYY_H_M(
                detailDYC?.createdDate,
              )}
            />

            <DetailItem
              icon={<IconPersonlabel width={16} height={16} />}
              label={t('CM.createdBy')}
              isUser={true}
              value={{
                name: createByDetail && createByDetail.personalName,
                email: createByDetail && createByDetail?.email,
                avatar: createByDetail && createByDetail?.imageUrl,
              }}
            />

            <DetailItem
              icon={<IconLabelReceiptStatus width={16} height={16} />}
              label={'Trạng thái yêu cầu'}
              value={
                <StatusTag status={detailDYC?.requestStatus} type="REQUEST" />
              }
            />

            <DetailItem
              icon={<IconLabelKey width={16} height={16} />}
              label={'Trạng thái quy trình'}
              value={
                <StatusTag status={detailDYC?.flowStatus} type="DEFAULT" />
              }
            />

            <View style={styles.bottomMenu}>
              {listActionNext.map(item => (
                <BottomItem
                  key={item.key}
                  action={item.key}
                  icon={item.icon}
                  label={item.label}
                  id={id}
                  detailDYC={detailDYC}
                />
              ))}
            </View>
          </View>
        </ScrollView>
      )}
    </>
  );
};

export default DetailDYCScreen;
