import {FlatList, ScrollView, TouchableOpacity, View} from 'react-native';

import {styles} from './styles';
import {useEffect, useState} from 'react';
import AttachmentItem from './component/attach-item';
import {listUploadData} from './helper';
import {MenuItem, OverflowMenu} from '@ui-kitten/components';
import {useTranslation} from 'react-i18next';
import Toast from 'react-native-toast-message';
import {useRoute} from '@react-navigation/native';
import {useAccountInfoServices} from '../../../../../../../hooks/apiHooks/useAccountInfoServices';
import {IReceiptAttach} from '../../../../../../../model/interface/receipt.interface';
import {useQDTHAService} from '../../../../../../../hooks/apiHooks/useAPI';
import {useUserZustandStore} from '../../../../../../../zutand/UserZustandStore';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Color, Font} from '../../../../../../../constants';
import {
  IconListtransferReceipt,
  IconUploadRed,
} from '../../../../../../../assets/images';
import TextCM from '../../../../../../components/Text';

const AttachmentsScreen = () => {
  const AccountService = useAccountInfoServices();
  const QDTHAServices = useQDTHAService();
  const [listAttachment, setListAttachment] = useState<IReceiptAttach[]>([]);
  const [totalAttachment, setTotalAttachment] = useState(0);

  const [currentPage, setCurrentPage] = useState(0);
  const router = useRoute<any>();
  const {ticketId} = router.params;
  const {t} = useTranslation();
  const [visible, setVisible] = useState(false);
  const {
    listCurrentUserInfo,
    uniqueUserEmails,
    setListCurrentUserInfo,
    setUniqueUserEmails,
  } = useUserZustandStore();
  const getListRelativeFile = async (page: number = 0) => {
    try {
      const data = await QDTHAServices.getDocumentReturn(ticketId);
      if (data?.data) {
        if (page === 0) {
          setListAttachment(data.data);
          setTotalAttachment(data?.totalRecords);
        } else {
          setListAttachment([...listAttachment, ...data.data]);
        }
        setCurrentPage(page + 1);

        const listCreated = Array.from(
          new Set(
            data.data
              .filter((item: any) => !uniqueUserEmails.has(item.createdBy))
              .map((item: any) => item.createdBy),
          ),
        );
        if (listCreated.length) {
          const filter = {
            logins: listCreated,
          };
          const resCreateBy = await AccountService.getListAccount(filter);
          if (resCreateBy?.data) {
            setListCurrentUserInfo([
              ...listCurrentUserInfo,
              ...resCreateBy.data,
            ]);
            const newSet = new Set([
              ...(uniqueUserEmails || []),
              ...listCreated.map((item: any) => item),
            ]);
            setUniqueUserEmails(newSet);
          }
        }
      }
    } catch (error) {
      console.error('error', error);
    }
  };
  useEffect(() => {
    getListRelativeFile();
  }, []);

  const callApitUploadFile = async (formData: FormData) => {
    try {
      let res;
      if (res) {
        Toast.show({
          type: 'success',
          text1: t('CM.noti'),
          text2: t('BLDT.upload_success'),
        });
        getListRelativeFile();
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('BLDT.error_upload_file'),
        });
      }
    } catch (error) {
      console.error(error);
    } finally {
      setVisible(false);
    }
  };

  const handleSelectImage = async () => {
    try {
      const formData = new FormData();
      formData.append('uploadFile', {});
      formData.append(
        'attachmentJson',
        JSON.stringify({
          ticketId: ticketId,
        }),
      );
      callApitUploadFile(formData);
    } catch (error) {
      console.error(error);
    }
  };

  const handleTakePhoto = async () => {
    try {
      const formData = new FormData();
      formData.append('uploadFile', {});
      formData.append(
        'attachmentJson',
        JSON.stringify({
          ticketId: ticketId,
        }),
      );
      callApitUploadFile(formData);
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: 'Lỗi',
        text2: t('BLDT.error_upload_file'),
      });
    }
  };

  const handleGetFormFile = async () => {
    try {
      const formData = new FormData();
      formData.append(
        'attachmentJson',
        JSON.stringify({
          ticketId: ticketId,
        }),
      );
      callApitUploadFile(formData);
    } catch (error) {
      console.error('error handleGetFormFile');
    }
  };
  const handleSelect = (value: string) => {
    switch (value) {
      case 'image':
        handleSelectImage();
        break;
      case 'takePhoto':
        handleTakePhoto();
        break;
      case 'file':
        handleGetFormFile();
        break;
      default:
        break;
    }
  };
  const toggleUpload = () => {
    setVisible(!visible);
  };

  return (
    <>
      <HeaderCM
        title={'Văn bản trả về'}
        useLinearGradient={false}
        style={{backgroundColor: Color.QDTHACMColor}}
        contentStyle={{backgroundColor: Color.QDTHACMColor}}
      />
      <View style={{backgroundColor: Color.White, flex: 1, padding: 16}}>
        <ScrollView
          style={styles.content}
          showsHorizontalScrollIndicator={false}
          showsVerticalScrollIndicator={false}>
          <View style={styles.sectionHeader}>
            <View style={styles.sectionTitleContainer}>
              <IconListtransferReceipt width={16} height={16} />
              <TextCM style={styles.sectionTitle}>{t('CM.attachment')}</TextCM>
            </View>
            {/* <OverflowMenu
              anchor={() => (
                <TouchableOpacity onPress={() => toggleUpload()}>
                  <View style={styles.uploadButton}>
                    <IconUploadRed width={10} height={10} />
                    <TextCM style={styles.uploadText}>{t('CM.upload')}</TextCM>
                  </View>
                </TouchableOpacity>
              )}
              visible={visible}
              onSelect={item => {
                handleSelect(listUploadData[item.row]?.value);
              }}
              onBackdropPress={() => setVisible(false)}>
              {listUploadData.map((item, index) => (
                <MenuItem
                  key={index}
                  title={() => (
                    <TextCM
                      style={{
                        textAlign: 'left',
                        fontFamily: Font.InterMedium500,
                      }}>
                      {t(item.key)}
                    </TextCM>
                  )}
                  accessoryLeft={() => item.icon}
                  style={{justifyContent: 'flex-start', columnGap: 8}}
                />
              ))}
            </OverflowMenu> */}
          </View>

          <View style={styles.documentList}>
            <FlatList
              data={listAttachment}
              renderItem={({item}) => (
                <AttachmentItem
                  item={item}
                  getListRelativeFile={getListRelativeFile}
                />
              )}
              showsVerticalScrollIndicator={false}
              showsHorizontalScrollIndicator={false}
              scrollEnabled={false}
              ListEmptyComponent={() => (
                <View
                  style={{
                    alignItems: 'center',
                    justifyContent: 'center',
                    flex: 1,
                  }}>
                  <TextCM>{t('CM.emptyData')}</TextCM>
                </View>
              )}
            />
            {listAttachment.length < totalAttachment && (
              <View style={{flexDirection: 'row', alignItems: 'center'}}>
                <View style={{flex: 1}}></View>
                <TouchableOpacity
                  onPress={() => getListRelativeFile(currentPage)}>
                  <TextCM style={styles.viewMore}>{t('TK.view-more')}</TextCM>
                </TouchableOpacity>
              </View>
            )}
          </View>
        </ScrollView>
      </View>
    </>
  );
};

export default AttachmentsScreen;
